/** A real 200×100 red PNG. */
export const PNG_200x100 =
  ''

/** A JPEG header whose SOF0 says 800×600 (enough for size parsing, not decoding). */
export const JPEG_800x600 = '/9j/4AAQSkZJRgAAAAAAAAAAAAD/wAARCAJYAyADAAAAAAAAAAAAAAAAAAAA/9k='

export const image = (mediaType: string, data: string) => ({
  type: 'image',
  source: { type: 'base64', media_type: mediaType, data },
})
